import json

W = "https://en.wiktionary.org/wiki/"
U_WEYS = W + "Reconstruction:Proto-Indo-European/weys-"
U_WEK = W + "Reconstruction:Proto-Indo-European/weḱ-"
U_BISH = W + "بیش"
U_BAS = W + "بس"
U_BISYAR = W + "بسیار"
U_BASANDA = W + "بسنده"
U_VIRUS_FA = W + "ویروس"
U_VIRUS = W + "virus"
U_HEKON = W + "ἑκών"
U_VISCUM = W + "viscum"
U_BISON = W + "bison"
U_WEASEL = W + "weasel"
U_OOZE = W + "ooze"
U_VISCOUS = W + "viscous"
V = "https://vajehyab.com/moein/"
U_MON_BISH, U_MON_VIRUS, U_MON_BAS, U_MON_BISYAR, U_MON_BASANDA = (V + w for w in ["بیش", "ویروس", "بس", "بسیار", "بسنده"])
U_ABADIS_BISH = "https://abadis.ir/fatofa/بیش/"

POK_WEIS = {"src": "POK", "where": "p. 1134 (POK_full.txt 'Root / lemma: ueis-3', Page(s):1134)", "stance": "supports",
            "note": "'ueis-3 Meaning: to flow; poison ... Avestan viš-, viša- poison, vaēsah- mould, dank decay, Verwesung ... gr. ios = Latin vīrus ... Old English wāse, engl. ooze slime, mud ... Old High German wisunt ... (from dem Germanic derives Latin bison) ... engl. weasel ... perhaps moreover IE *uiks- Mistel ... Latin viscum'"}
WLD_WEIS = {"src": "WLD", "where": "Bd. I (WLD_Bd1_pages.txt leaf 253; WP I 234 f.)", "stance": "supports",
            "note": "'av. viš-, viša- „Gift“, vaēsah- „Moder, Verwesung“ (Bartholomae Airan. Wb. 1329 ...). Gr. ios „Gift“ = lat. virus „zähe Flüssigkeit, Schleim, Saft ... bes. Gift“ = ir. fí ... ags. wāse „Schlamm“'"}
AHD_WEIS = {"src": "AHD", "where": "Watkins 1985 s.v. weis- (AHD_watkins1985.txt l.1137-1140)", "stance": "partial",
            "note": "'weis-. To flow. 1. Germanic *wisōn-, waisōn- in Old English wāse, mire, mud: OOZE2. 2. Taken by many as a derivative of this root, but probably an independent Indo-European word, is ... *wis-o- in Latin vīrus ... 3. Extended zero-grade form *wisk- possibly in Latin viscum ... II. Attributed by some to this root, but more likely of obscure origin, are some Germanic words for strong-smelling animals ... *wisulōn- ... WEASEL ... *wisand- ... BISON. [Pok. 3. weis- 1134.]'"}
SYN_POISON = {"src": "SYN", "where": "§4.89 POISON (SYN.txt l.7128, 7973)", "stance": "partial",
              "note": "Buck: 'Skt. viṣa-, Av. viš-, viša-, Grk. ios, Lat. vīrus ... root connection dub. (possibly an IE specialization of \"fluid\" to \"poisonous fluid\", but evidence of an IE *weis- \"flow\" meager). Walde-P. 1.248 f.'"}
IEC_WEIS = {"src": "IEC", "where": "IEC.txt l.20400 s.v. uisolos (1)", "stance": "partial",
            "note": "Mann: 'uisolos (1) poisonous, foul. Cf. uis- (3) ... Skt. visráh musty; Lat. cf. virul-entus' - Mann sets up a separate *uis- 'poison' base rather than one root 'flow'."}

entries = []

# ---------------- entry 0 : Weis ----------------
e0_nodes = [
 {
  "id": 1, "lang": "Avestan", "words": "vaeša; viš 1, viša", "verdict": "confirmed",
  "derivation": "Avestan vaēšah- n. 'mould, decay, putrefaction' (Bartholomae col. 1329, compared with OHG wesanēn 'to rot') is the full-grade s-stem *wóys-/wéys-es- of PIE *weys- 'to flow; rot', and Avestan viš- / viša- n. 'poison' (Bartholomae s.v. viša-, = Skt. viṣá-) continues the zero-grade *wis-ó-, the same formation as Latin vīrus and Greek ios. Nourai's gloss 'rotten food' for viš is loose (the attested sense is 'poison'), but forms, language and descent are correct.",
  "derivation_fa": "واژه‌های اوستایی vaēšah- «کپک، پوسیدگی» و viš- / viša- «زهر» هر دو از ریشهٔ هندواروپایی آغازین *weys- «روان شدن، گندیدن» اند: نخستی با درجهٔ کامل و پسوند -ah-، دومی با درجهٔ صفر *wis-ó- که هم‌ریشهٔ سنسکریت viṣa «زهر»، یونانی ios و لاتین vīrus است. بارتولمه (ستون ۱۳۲۹) vaēšah- را «پوسیدگی، Moder» و viša- را «زهر» معنا کرده است. ادعای نورایی درست است؛ تنها معنای «خوراک گندیده» برای viš دقیق نیست.",
  "sources": [U_WEYS, U_VIRUS],
  "ref_check": [
   {"ref": "POK:1134", "status": "supports", "note": "POK_full.txt 'ueis-3 ... Page(s):1134': 'Avestan viš-, viša- poison, vaēsah- mould, dank decay, Verwesung'."},
   {"ref": "KLN:1714", "status": "supports", "note": "Klein s.v. virus (1966 two-volume file is truncated before 'v', read in KLN_1971.txt l.262734): 'L. virus, poison ... fr. I.-E. base *weis-, to melt away, rot, whence also OI. viṣám, poison ... Avestic viš-, visha-, poison, vaēshah-, mold, Gk. ios'. Exactly Nourai's Avestan forms and the root gloss 'melt away, rot'."}
  ],
  "consulted": [
   {"src": "BRT", "where": "col. 1329 s.v. vaēšah-; s.v. viša- (BRT.txt leaves 731, 806)", "stance": "supports", "note": "'vaēšah- n. Moder, Verwesung; Ort der Verwesung ... Vgl. ahd. wesanēn faul werden'; 'viša- n. Gift ... ai. viṣá- n.; vgl. mp. viš, np. bēš (wozu Hbm. PSt 270)'."},
   WLD_WEIS, POK_WEIS
  ]
